#include <iostream>
#include <vector>
#include <memory>
#include <iomanip>

class Account {
protected:
    double balance{0.0};
public:
    explicit Account(double initialBalance) : balance(initialBalance >= 0.0 ? initialBalance : 0.0) {}
    virtual ~Account() = default;

    virtual bool credit(double amount) {
        if (amount > 0.0) {
            balance += amount;
            return true;
        }
        return false;
    }

    virtual bool debit(double amount) {
        if (amount > 0.0 && amount <= balance) {
            balance -= amount;
            return true;
        }
        return false;
    }

    double getBalance() const { return balance; }
};

class SavingsAccount : public Account {
private:
    double interestRate{0.0};
public:
    SavingsAccount(double initialBalance, double rate)
        : Account(initialBalance), interestRate(rate > 0.0 ? rate : 0.0) {}

    double calculateInterest() const {
        return balance * interestRate;
    }
};

class CheckingAccount : public Account {
private:
    double transactionFee{0.0};
public:
    CheckingAccount(double initialBalance, double fee)
        : Account(initialBalance), transactionFee(fee >= 0.0 ? fee : 0.0) {}

    bool debit(double amount) override {
        if (Account::debit(amount)) {
            balance -= transactionFee;
            return true;
        }
        return false;
    }
};

int main() {
    std::vector<std::unique_ptr<Account>> accounts;
    accounts.push_back(std::make_unique<SavingsAccount>(1000.0, 0.05));
    accounts.push_back(std::make_unique<CheckingAccount>(500.0, 2.50));

    std::cout << std::fixed << std::setprecision(2);

    for (size_t i = 0; i < accounts.size(); ++i) {
        std::cout << "Account " << (i + 1) << " initial: $" << accounts[i]->getBalance() << "\n";
        accounts[i]->credit(100.0);
        accounts[i]->debit(50.0);

        auto savings = dynamic_cast<SavingsAccount*>(accounts[i].get());
        if (savings) {
            double interest = savings->calculateInterest();
            savings->credit(interest);
            std::cout << "  [Savings interest applied: $" << interest << "]\n";
        }

        std::cout << "  Final balance: $" << accounts[i]->getBalance() << "\n";
    }

    return 0;
}

#include <iostream>
#include <vector>
#include <memory>
#include <string>
#include <iomanip>

class CarbonFootprint {
public:
    virtual ~CarbonFootprint() = default;
    virtual double getCarbonFootprint() const = 0;
    virtual std::string getIdentification() const = 0;
};

class Building : public CarbonFootprint {
private:
    double electricKwhMonthly;
    int occupants;
public:
    Building(double kwh, int people) : electricKwhMonthly(kwh), occupants(people) {}

    double getCarbonFootprint() const override {
        // Factor: ~0.85 kg CO2 per kWh annually
        return (electricKwhMonthly * 12.0 * 0.85) / occupants;
    }

    std::string getIdentification() const override {
        return "Building (" + std::to_string(occupants) + " occupants)";
    }
};

class Car : public CarbonFootprint {
private:
    double milesDrivenAnnual;
    double milesPerGallon;
public:
    Car(double miles, double mpg) : milesDrivenAnnual(miles), milesPerGallon(mpg) {}

    double getCarbonFootprint() const override {
        // Factor: ~8.887 kg CO2 per gallon of gasoline
        return (milesDrivenAnnual / milesPerGallon) * 8.887;
    }

    std::string getIdentification() const override {
        return "Gasoline Automobile";
    }
};

class Bicycle : public CarbonFootprint {
private:
    std::string brand;
public:
    explicit Bicycle(std::string b) : brand(std::move(b)) {}

    double getCarbonFootprint() const override {
        return 0.0; // Zero operational direct emissions
    }

    std::string getIdentification() const override {
        return "Bicycle [" + brand + "]";
    }
};

int main() {
    std::vector<std::unique_ptr<CarbonFootprint>> entities;
    entities.push_back(std::make_unique<Building>(2500.0, 5));
    entities.push_back(std::make_unique<Car>(12000.0, 30.0));
    entities.push_back(std::make_unique<Bicycle>("Trek Road Bike"));

    std::cout << std::fixed << std::setprecision(2);
    for (const auto& entity : entities) {
        std::cout << entity->getIdentification() 
                  << " -> Annual Footprint: " 
                  << entity->getCarbonFootprint() << " kg CO2\n";
    }

    return 0;
}
